item.content:encoded:
/*
You can add your own CSS here.

Click the help icon above to learn more.
*/
body{
	background-color: #fff !important;
}

.geodir-loc-bar{
	padding: 0px !important;
	border: 0px !important;
	margin: 0px !important;
}
.geodir-loc-bar-in {
    background: #f3f3f3;
    border: 0px !important;
    padding: 10px;
    margin: 0 auto;
    width: 80%;
}
.bestof-tabs-on-left dl.geodir-tab-head dd {
    float: left !important;
    width: 100%;
    border-bottom: 1px solid #E1E1E1;
}

.buddypress .content-wrapper {
padding-top: 0;
padding-bottom: 0;
}
a.btn-login, a.btn-register {
    color: #1d70a3;
    font-size: 14px;
}
/**/
.page-id-2894 .geodir-listing-search .gd-search-input-wrapper input.search_text, .page-id-2894 .gd-search-input-wrapper input.snear {
    border-radius: 50px !important;
}
.page-id-2894 .geodir-listing-search button.geodir_submit_search i.fa.fa-search {
    font-size: 25px;
}
.page-id-2894 .geodir-listing-search button.geodir_submit_search:hover {
    color: #fff !important;
}
.page-id-2894 .geodir-listing-search .geodir-loc-bar-in {
    background: transparent;
}
.page-id-2894 .geodir-listing-search button.geodir_submit_search {
    border: none;
}
.interest .elementor-element-dab5423 {
    border: 3px solid;
    border-radius: 100%;
    padding: 67px 15px;
    transform: rotate(-35Deg);
    border-color: #ffd9ff #fc4fdd #5ed5cb #ffb739;
}
.interest h5 {
    text-align: center;
    color: #fff;
}
.interest .geodir-cat-list ul li {
    border: none;
    margin-right: 3px;
}
.interest .geodir-cat-list ul li a {
    color: #fff;
}
.interest .geodir-cat-list-more {
    display: none;
}
.interest span.geodir_term_class {
    display: none;
}
.interest .geodir-category-list-in {
    border:  none;
    padding:  0px;
    margin-bottom: 0px;
}
.latest_places .geodir_locations {
    border: none;
}
.latest_places a.geodir-viewall {
    display: none;
}
.latest_places .geodir_list_heading {
    text-align: center;
}
.latest_places h5 {
    font-size: 59px;
}
.geodir_category_list_view li.gridview_onefourth {
    box-shadow: 0 0 10px 0 rgba(0,0,0,.15);
    border: none;
    padding: 0px;
    margin-left:  10px;
    margin-right: 10px;
    border-radius: 3px !important;
}
.latest_places .geodir_locations.geodir_location_listing {
    padding: 0px;
}
.latest_places .geodir-content {
    padding: 0px 30px !important;
    margin: 0px !important;
    width: 100% !important;
}
.latest_places .geodir-addinfo.clearfix {
    padding: 15px 30px;
    border-top: 1px solid #eaeaea;
    margin: 0px !important;
    width: 100% !important;
}
.latest_places .geodir_category_list_view li.gridview_onefourth:hover {
    box-shadow: 0 0 30px 0 rgba(0,0,0,.15);
}
.page-id-2894 .elementor-element-c750e3e article h3.elementor-post__title {
    text-overflow: ellipsis;
    overflow: hidden;
    white-space: nowrap;
}
@media only screen and (min-width:1025px){
.geodir_category_list_view li.gridview_onefourth {
    width: 23%;
}
}
@media only screen and (min-width:768px) and (max-width:1024px){
.geodir_category_list_view li.gridview_onefourth {
    width: 46%;
}
}
@media only screen and (max-width:767px){
.geodir_category_list_view li.gridview_onefourth {
    width: 100%;
}
}
/*snow-fall*/
.bubbles_wrap {
    position: fixed;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    z-index: 0;
    overflow: hidden;
}
.bubble {
    border-radius: 50%;
    box-shadow: none;
    height: 5px;
    position: absolute;
    width: 5px;
}
.x1 {
    -webkit-animation: animateBubble 15s linear infinite, sideWays 2s ease-in-out infinite alternate;
    -moz-animation: animateBubble 15s linear infinite, sideWays 2s ease-in-out infinite alternate;
    animation: animateBubble 15s linear infinite, sideWays 2s ease-in-out infinite alternate;
    left: 6%;
    top: 45%;
    background: #ffb739;
}
.x2 {
    -webkit-animation: animateBubble 10s linear infinite, sideWays 4s ease-in-out infinite alternate;
    -moz-animation: animateBubble 10s linear infinite, sideWays 4s ease-in-out infinite alternate;
    animation: animateBubble 10s linear infinite, sideWays 4s ease-in-out infinite alternate;
    left: 5%;
    top: 80%;
    background: #fc4fdd;
}
.x3 {
    -webkit-animation: animateBubble 18s linear infinite, sideWays 2s ease-in-out infinite alternate;
    -moz-animation: animateBubble 18s linear infinite, sideWays 2s ease-in-out infinite alternate;
    animation: animateBubble 18s linear infinite, sideWays 2s ease-in-out infinite alternate;
    left: 10%;
    top: 40%;
    background: #5ed5cb;
}
.x4 {
    -webkit-animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    -moz-animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    left: 20%;
    top: 0;
    background: #3de4a3;
}
.x5 {
    -webkit-animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    -moz-animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    left: 30%;
    top: 50%;
    background: #fc4fb1;
}
.x6 {
    -webkit-animation: animateBubble 11s linear infinite, sideWays 2s ease-in-out infinite alternate;
    -moz-animation: animateBubble 11s linear infinite, sideWays 2s ease-in-out infinite alternate;
    animation: animateBubble 11s linear infinite, sideWays 2s ease-in-out infinite alternate;
    left: 50%;
    top: 0;
    background: #2c4aff;
}
.x7 {
    -webkit-animation: animateBubble 10s linear infinite, sideWays 2s ease-in-out infinite alternate;
    -moz-animation: animateBubble 10s linear infinite, sideWays 2s ease-in-out infinite alternate;
    animation: animateBubble 10s linear infinite, sideWays 2s ease-in-out infinite alternate;
    left: 65%;
    top: 70%;
    background: #ffb739;
}
.x8 {
    -webkit-animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    -moz-animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    animation: animateBubble 12s linear infinite, sideWays 3s ease-in-out infinite alternate;
    left: 80%;
    top: 10%;
    background: #8f3de4;
}
.x9 {
    -webkit-animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    -moz-animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    animation: animateBubble 19s linear infinite, sideWays 4s ease-in-out infinite alternate;
    left: 90%;
    top: 50%;
    background: #fff339;
}
.x10 {
    -webkit-animation: animateBubble 16s linear infinite, sideWays 2s ease-in-out infinite alternate;
    -moz-animation: animateBubble 16s linear infinite, sideWays 2s ease-in-out infinite alternate;
    animation: animateBubble 16s linear infinite, sideWays 2s ease-in-out infinite alternate;
    left: 80%;
    top: 80%;
    background: #fc4f4f;
}

.home .content-wrapper .entry-header.page-header, .content-wrapper header.woocommerce-products-header {
    border-bottom: 0px solid rgba(0, 0, 0, 0.1);
    margin-bottom: 0px;
}

.gd_place-template-default.single.single-gd_place .geodir_full_page {
	display: none;
}
.footer-menu a{
	color: #777;
}
.rg-count{
	color: #fff;
  background-color: #000;
}

